#include <algorithm>

const FIT_UINT16 Profile::GetFieldIndex(const FIT_UINT16 mesgNum, const FIT_UINT8 fieldNum)
{
    const MESG *mesg = GetMesg(mesgNum);

    if (mesg == NULL)
        return FIT_UINT16_INVALID;

    // Use std::find_if with a lambda for potential compiler optimization and clearer intent
    const auto it = std::find_if(mesg->fields, mesg->fields + mesg->numFields,
        [fieldNum](const FIELD& f) { return f.num == fieldNum; });

    return (it != mesg->fields + mesg->numFields) ? static_cast<FIT_UINT16>(it - mesg->fields) : FIT_UINT16_INVALID;
}
